head.script:
// 광고주 A1~A15 + B 50건(GridView 높이보다 많은 65건)
scwin.makeLongData = function() {
	var rows = [];
	for (var i = 1; i <= 15; i++) {
		rows.push({"rec_no": String(i), "cliCode": "C" + i, "cliName": "A" + i, "opCnt": "1"});
	}
	for (var j = 16; j <= 65; j++) {
		rows.push({"rec_no": String(j), "cliCode": "C" + j, "cliName": "B", "opCnt": "1"});
	}
	return rows;
};
scwin.grd_TrdStat_ongroupby = function(options) {
	options.groupbyHeader = [{
		colSpan: "4",
		inputType: "expression",
		expression: " toggle() + depthStr() + ' [ ' + count() + ' 건 ] ' ",
		align: "left"
	}];
	options.groupbyFooter = [{
		colSpan: "3"
	}, {
		colSpan: "1",
		inputType: "expression",
		expression: "SUM('opCnt')",
		align: "right"
	}];
	grd_TrdStat.groupby(options);
};
scwin.trigger1_onclick = function(e) {
	dl_listMain.setJSON(scwin.makeLongData());
};
// GridView 높이보다 적은 4건
scwin.trigger2_onclick = function(e) {
	dl_listMain.setJSON([
		{"rec_no": "1", "cliCode": "C1", "cliName": "A1", "opCnt": "1"},
		{"rec_no": "2", "cliCode": "C2", "cliName": "A2", "opCnt": "1"},
		{"rec_no": "3", "cliCode": "C3", "cliName": "A3", "opCnt": "1"},
		{"rec_no": "4", "cliCode": "C4", "cliName": "B", "opCnt": "1"}
	]);
};
scwin.trigger3_onclick = function(e) {
	dl_listMain.setJSON(scwin.makeLongData());
};
